#if NET7_0_OR_GREATER
#pragma warning disable IDE0052, IDE0060

namespace Gori.StaticInstances.Examples
{
    /// <summary>
    /// Example showing <see cref="StaticInstanceAttribute"/> used alongside <see cref="SingletonAttribute"/>.
    /// The default <c>Instance</c> property is generated by <c>[Singleton]</c>.
    /// Additional named properties are generated for each <c>[StaticInstance]</c> constructor.
    /// </summary>
    public partial record StaticInstanceExample()
    {
        private readonly string host = "";
        private readonly int    port;

        [StaticInstance("localhost", 5432, Name = "Development")]
        [StaticInstance("staging-host", 5432, Name = "Staging")]
        private StaticInstanceExample(string host, int port) : this()
        {
            this.host = host;
            this.port = port;
        }

        [StaticInstance("prod-host", 5433, true, Name = "Production", Internal = true)]
        private StaticInstanceExample(string host, int port, bool useTLS) : this()
        {
            this.host = host;
            this.port = port;
        }
    }
}

#endif

